using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Greets a user by name.")]
    public static string Greet(
        [Description("The user's name")] string name) =>
        $"Hello, {name}! Welcome to the HTTP MCP server.";

    [McpServerTool, Description("Returns the current server time in UTC.")]
    public static string GetServerTime() =>
        DateTime.UtcNow.ToString("o");
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(
        UriTemplate = "config://app",
        Name = "App Config",
        MimeType = "application/json"),
     Description("Returns application configuration data.")]
    public static string GetAppConfig() =>
        JsonSerializer.Serialize(new
        {
            AppName = "HttpMcpServer",
            Version = "1.0.0",
            Environment = Environment.GetEnvironmentVariable("ASPNETCORE_ENVIRONMENT") ?? "Production",
            MaxConnections = 100,
            Features = new { Logging = true, Caching = false }
        }, new JsonSerializerOptions { WriteIndented = true });

    [McpServerResource(
        UriTemplate = "config://endpoints",
        Name = "API Endpoints",
        MimeType = "application/json"),
     Description("Lists available API endpoints and their descriptions.")]
    public static string GetEndpoints() =>
        JsonSerializer.Serialize(new[]
        {
            new { Path = "/mcp", Description = "MCP Streamable HTTP endpoint" },
            new { Path = "/health", Description = "Health check" }
        }, new JsonSerializerOptions { WriteIndented = true });
}

